import {
  generateCarbonTagZpl,
  stripRfidEncoding,
  deriveItemNumber,
  DEFAULT_CARBON_TAG_SETTINGS,
  type CarbonTagInput,
} from "@/lib/utils/zpl-carbon-tag";

/**
 * 203-dpi Carbon tag rendering for the second Zebra (.220, a 203-dpi ZD500R) non-RFID printer, plus a
 * 300-dpi RFID preview that mirrors what `generateCarbonTagZpl` actually prints
 * to the Zebra (.3). Both share the one tuned design so the Print Tags page
 * preview == print.
 *
 * Non-RFID path: take the 300-dpi `generateCarbonTagZpl`, strip the chip encode,
 * scale to 203 dpi, nudge content right +28, and pin the Carbon box icon
 * bottom-right. Tuned on-printer 2026-06-01 (see
 * project_zebra_220_static_ip_2026_05_05 memory). REQUIRES E:ARIAL.TTF +
 * E:LSB3.TTF on the target printer.
 */

// Carbon open-box icon (~15 mm), baked to 203-dpi from box.png as a ^GF field.
const BOX_ICON_GFA =
  "^GFA,1785,1785,15,";

const S = 203 / 300;
const R = (n: number) => Math.round(n * S);

/** Scale a 300-dpi Carbon-tag ZPL down to 203 dpi (every dot-valued param). */
export function scaleZplTo203(zpl: string): string {
  return zpl
    .replace(/\^PW(\d+)/g, (_m, n) => `^PW${R(+n)}`)
    .replace(/\^LL(\d+)/g, (_m, n) => `^LL${R(+n)}`)
    .replace(/\^LS(-?\d+)/g, (_m, n) => `^LS${R(+n)}`)
    .replace(/\^LT(-?\d+)/g, (_m, n) => `^LT${R(+n)}`)
    .replace(/\^(FO|FT)(-?\d+),(-?\d+)/g, (_m, c, x, y) => `^${c}${R(+x)},${R(+y)}`)
    .replace(/\^GB(\d+),(\d+),(\d+)/g, (_m, w, h, t) => `^GB${R(+w)},${R(+h)},${Math.max(1, R(+t))}`)
    .replace(
      /\^BY(\d+)(,\d+(?:\.\d+)?)?(,\d+)?/g,
      (_m, mod, ratio, h) =>
        `^BY${Math.max(1, R(+mod))}${ratio ?? ""}${h ? "," + R(+h.slice(1)) : ""}`,
    )
    .replace(
      /\^A([A-Z0-9])([NBRI]),(\d+)(,\d+)?/g,
      (_m, f, o, h, w) => `^A${f}${o},${R(+h)}${w ? "," + R(+w.slice(1)) : ""}`,
    )
    .replace(/\^FB(\d+),(\d+),(\d+),([LCRJ])/g, (_m, w, l, sp, j) => `^FB${R(+w)},${l},${R(+sp)},${j}`)
    .replace(/\^BA([NBRI]),(\d+)/g, (_m, o, h) => `^BA${o},${R(+h)}`)
    .replace(/\^BC([NBRI]),(\d+)/g, (_m, o, h) => `^BC${o},${R(+h)}`);
}

/** One non-RFID Carbon tag for the 203-dpi Zebra at .220, box icon included. */
export function generateNonRfidTag203(input: CarbonTagInput): string {
  const full = generateCarbonTagZpl({
    input,
    settings: DEFAULT_CARBON_TAG_SETTINGS,
    epcWrite: { companyPrefix: 0, itemNumber: 0, serialNumber: 0 },
  });
  let z = scaleZplTo203(stripRfidEncoding(full));
  // tuned 2x3 / 203-dpi geometry (^LL = the calibrated 2" label length, 414).
  // Drop ^MD — on the .220 Zebra firmware ^MD stacks on print.tone and maxes
  // darkness; darkness is set on the printer (print.tone 4) instead.
  z = z
    .replace(/\^MD\d+\r?\n/, "")
    .replace(/\^PW\d+/, "^PW670")
    .replace(/\^LL\d+/, "^LL414")
    .replace(/\^LS-?\d+/, "^LS0")
    .replace(/\^LT-?\d+/, "^LT8");
  // nudge content right +28 (icon added afterwards, so only content moves)
  z = z.replace(/\^(FO|FT)(-?\d+),(-?\d+)/g, (_m, c, x, y) => `^${c}${+x + 28},${y}`);
  // Carbon box icon, flush bottom-right
  z = z.replace("^PQ", `^FO549,137${BOX_ICON_GFA}^FS\n^PQ`);
  return z;
}

export function generateNonRfidTag203Batch(input: CarbonTagInput, qty: number): string {
  return Array.from({ length: Math.max(1, qty) }, () => generateNonRfidTag203(input)).join("\n");
}

/** 300-dpi RFID tag preview — mirrors the commission print (`generateCarbonTagZpl`). */
export function generateRfidTagPreview(
  input: CarbonTagInput,
  sysid: string | number,
  companyPrefix: number,
  serial: number,
): string {
  const itemNumber = Number(deriveItemNumber(String(sysid)).toString());
  return generateCarbonTagZpl({
    input,
    settings: DEFAULT_CARBON_TAG_SETTINGS,
    epcWrite: { companyPrefix, itemNumber, serialNumber: serial },
  });
}

export function generateRfidTagPreviewBatch(
  input: CarbonTagInput,
  sysid: string | number,
  companyPrefix: number,
  startSerial: number,
  qty: number,
): string {
  return Array.from({ length: Math.max(1, qty) }, (_v, i) =>
    generateRfidTagPreview(input, sysid, companyPrefix, startSerial + i),
  ).join("\n");
}
